425 public applyVersionFilter(
426   handler: Function,
427   version: VersionValue,
428   versioningOptions: VersioningOptions,
429 ): VersionedRoute {
430   const callNextHandler: VersionedRoute = (req, res, next) => {
431     if (!next) {
432       throw new InternalServerErrorException(
433         'HTTP adapter does not support filtering on version',
434       );
435     }
436     return next();
437   };
439   if (
440     version === VERSION_NEUTRAL ||
441     // URL Versioning is done via the path, so the filter continues forward
442     versioningOptions.type === VersioningType.URI
443   ) {
444     const handlerForNoVersioning: VersionedRoute = (req, res, next) =>
445       handler(req, res, next);
447     return handlerForNoVersioning;
448   }
450   // Custom Extractor Versioning Handler
451   if (versioningOptions.type === VersioningType.CUSTOM) {
452     const handlerForCustomVersioning: VersionedRoute = (req, res, next) => {
453       const extractedVersion = versioningOptions.extractor(req);
455       if (Array.isArray(version)) {
456         if (
457           Array.isArray(extractedVersion) &&
458           version.filter(v => extractedVersion.includes(v as string)).length
459         ) {
460           return handler(req, res, next);
461         }
463         if (
464           isString(extractedVersion) &&
465           version.includes(extractedVersion)
466         ) {
467           return handler(req, res, next);
468         }
469       } else if (isString(version)) {
470         // Known bug here - if there are multiple versions supported across separate
471         // handlers/controllers, we can't select the highest matching handler.
472         // Since this code is evaluated per-handler, then we can't see if the highest
473         // specified version exists in a different handler.
474         if (
475           Array.isArray(extractedVersion) &&
476           extractedVersion.includes(version)
477         ) {
478           return handler(req, res, next);
479         }
481         if (isString(extractedVersion) && version === extractedVersion) {
482           return handler(req, res, next);
483         }
484       }
486       return callNextHandler(req, res, next);
487     };
489     return handlerForCustomVersioning;
490   }
492   // Media Type (Accept Header) Versioning Handler
493   if (versioningOptions.type === VersioningType.MEDIA_TYPE) {
494     const handlerForMediaTypeVersioning: VersionedRoute = (
495       req,
496       res,
497       next,
498     ) => {
499       const MEDIA_TYPE_HEADER = 'Accept';
500       const acceptHeaderValue: string | string[] | undefined =
501         req.headers?.[MEDIA_TYPE_HEADER] ||
502         req.headers?.[MEDIA_TYPE_HEADER.toLowerCase()];
504       const headerVersion = getMediaTypeVersion(
505         acceptHeaderValue,
506         versioningOptions.key,
507       );
509       // No version was supplied
510       if (isUndefined(headerVersion)) {
511         if (Array.isArray(version)) {
512           if (version.includes(VERSION_NEUTRAL)) {
513             return handler(req, res, next);
514           }
515         }
516       } else {
517         if (Array.isArray(version)) {
518           if (version.includes(headerVersion)) {
519             return handler(req, res, next);
520           }
521         } else if (isString(version)) {
522           if (version === headerVersion) {
523             return handler(req, res, next);
524           }
525         }
526       }
528       return callNextHandler(req, res, next);
529     };
531     return handlerForMediaTypeVersioning;
532   }
534   // Header Versioning Handler
535   if (versioningOptions.type === VersioningType.HEADER) {
536     const handlerForHeaderVersioning: VersionedRoute = (req, res, next) => {
537       const customHeaderVersionParameter: string | undefined =
538         req.headers?.[versioningOptions.header] ||
539         req.headers?.[versioningOptions.header.toLowerCase()];
541       // No version was supplied
542       if (isUndefined(customHeaderVersionParameter)) {
543         if (Array.isArray(version)) {
544           if (version.includes(VERSION_NEUTRAL)) {
545             return handler(req, res, next);
546           }
547         }
548       } else {
549         if (Array.isArray(version)) {
550           if (version.includes(customHeaderVersionParameter)) {
551             return handler(req, res, next);
552           }
553         } else if (isString(version)) {
554           if (version === customHeaderVersionParameter) {
555             return handler(req, res, next);
556           }
557         }
558       }
560       return callNextHandler(req, res, next);
561     };
563     return handlerForHeaderVersioning;
564   }
566   throw new Error('Unsupported versioning options');
567 }
